# DK ARG.  Aabenraa - Gråsten
#
let ag = path("d3.dk.arg");

with detail = 3, railway = :first :g1000 :pax :removed {
    with link = "point.dk.Aabenraa-Amtsb", railway = :station {
        track(ag[:aba - 0.5sw, :aba + 0.5sw]);
        with layer = 1 marker(:right :de.bf :casing, ag[:aba - 0.3sw] >> 0.5mt);
    }

    with link = "line.dk.ARG" {
        track(ag[:aba + 0.49sw, :abs - 0.49sw]);
    }

    with link = "point.dk.Aabenraa-Sønderport", railway = :station {
        track(ag[:abs - 0.5sw, :abs + 0.5sw]);
        marker(:right :de.hst, ag[:abs] >> 0.5mt);
    }

    with link = "line.dk.ARG" {
        track(ag[:abs + 0.49sw, :abs + 1.01km]);
        line_label(:left:w, ag[:abs + 1km] << 0.5mt, "ARG");
        track(ag[:abs + 0.99km, :ske - 0.49sw]);
    }

    with link = "point.dk.Skelbæk-Sønderjylland", railway = :station {
        track(ag[:ske - 0.5sw, :ske + 0.5sw]);
        marker(:left :de.hp, ag[:ske] << 0.5mt);
        slabel(:left, ag[:ske] >> 0.5mt + (-1.2dt, 0.5dt),
            "Skelbæk"
        );
    }

    with link = "line.dk.ARG" {
        track(ag[:ske + 0.49sw, :sty - 0.49sw]);
    }

    with link = "point.dk.Styrtom", railway = :station {
        track(ag[:sty - 0.5sw, :sty + 0.5sw]);
        marker(:left :de.hp, ag[:sty] << 0.5mt);
        slabel(:right, ag[:sty] << 0.5mt << 1sh + (1.3dt, 0.3dt),
            "Styrtom"
        );
    }

    with link = "line.dk.ARG" {
        track(ag[:sty + 0.49sw, :stu - 0.49sw]);
    }

    with link = "point.dk.Stubbæk", railway = :station {
        track(ag[:stu - 0.5sw, :stu + 0.5sw]);
        marker(:right :de.hp, ag[:stu - 0.3sw] >> 0.5mt);
        slabel(:left, ag[:stu] >> 0.5mt >> 1sh + (-2.1dt, 0.6dt),
            "Stubbæk"
        );
    }

    with link = "line.dk.ARG" {
        track(ag[:stu + 0.49sw, :sho - 0.49sw]);
    }

    with link = "point.dk.Sønder-Hostrup", railway = :station {
        track(ag[:sho - 0.5sw, :sho + 0.5sw]);
        marker(:left :de.hp, ag[:sho] << 0.5mt);
        slabel(:left, ag[:sho] >> 0.5mt + (-1.5dt, 1dt),
