        track(ag[:sho + 0.89km, :nba - 0.49sw]);
    }

    with link = "point.dk.Nørballe", railway = :station {
        track(ag[:nba - 0.5sw, :nba + 0.5sw]);
        marker(:left :de.hp, ag[:nba] << 0.5mt);
        slabel(:top, ag[:nba] << 0.5mt << 1sh << 0.3dt,
