        slabel(:bottom, ag[:tum] >> 0.5mt + (2dt, 0.4dt),
            "Tumbøl"
        );
    }

    with link = "line.dk.ARG" {
        track(ag[:tum + 0.49sw, :sly - 0.49sw]);
    }

    with link = "point.dk.Slyngsten", railway = :station {
        track(ag[:sly - 0.5sw, :sly + 0.5sw]);
        marker(:right :de.hp, ag[:sly] >> 0.5mt);
        slabel(:right, ag[:sly] >> 0.5mt >> 1sh + (1.2dt, 1dt),
