        );
    }

    with link = "line.dk.ARG" {
        track(ag[:bog + 0.49sw, :sko - 0.49sw]);
    }

    with link = "point.dk.Skovbølgård", railway = :station {
        track(ag[:sko - 0.5sw, :sko + 0.5sw]);
        marker(:right :de.hp, ag[:sko] >> 0.5mt);
        slabel(:left, ag[:sko] << 0.5mt + (-1.2dt, 0.3dt),
            "Skovbølgård"
