    }

    with link = "line.dk.ARG" {
        track(ag[:sko + 0.49sw, :var - 0.49sw]);
    }

    with link = "point.dk.Varnæs" {
        track(ag[:var - 0.5sw, :var + 0.5sw]);
        marker(:left :de.bf, ag[:var] << 0.5mt);
        slabel(:top, ag[:var] << 0.5mt << 1sh << 0.4dt,
            "Varnæs"
        );
    }

    with link = "line.dk.ARG" {
        track(ag[:var + 0.49sw, :bov - 0.49sw]);
    }

    with link = "point.dk.Bovrup" {
        track(ag[:bov - 0.5sw, :bov + 0.5sw]);
