        slabel(:left, ag[:gro] >> 0.5mt >> 1sh + (-1.4dt, 1.1dt),
            "Grøngrøft"
        );
    }

    with link = "line.dk.ARG" {
        track(ag[:gro + 0.49sw, :fsk - 0.49sw]);
