    with link = "point.dk.Fiskbækskov" {
        track(ag[:fsk - 0.5sw, :fsk + 0.5sw]);
        marker(:left :de.hp, ag[:fsk] << 0.5mt);
        slabel(:right, ag[:fsk] << 0.5mt << 1sh + (-2dt, -0.9dt),
