    with link = "point.dk.Fiskbæk" {
        track(ag[:fis - 0.5sw, :fis + 0.5sw]);
        marker(:right :de.hp, ag[:fis] >> 0.5mt);
        slabel(:left, ag[:fis] >> 0.5mt >> 1sh + (-1.3dt, 1.1dt),
