    }

    with link = "line.dk.ARG" {
        track(ag[:fis + 0.49sw, :gra.xa - 2mt]);
        track(:lor,
                ag[:gra.xa - 2.1mt, :gra.xa - 2mt]
            ..  ag[:gra.ya, :gra.ya + 0.1dl] >> 1ms >> 1mt
        );
        track(:lor, ag[:gra.ya, :gra - 0.49sw] >> 1ms >> 1mt);
    }

    # point.dk.Gråsten  dk.SBT
}

